export const tableFilterGuideExamples = {};
const ex = tableFilterGuideExamples;

const esc = (value) => String(value).replace(/[&<>"]/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[character]);

function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = '';
  let quoted = false;
  const input = text.replace(/^﻿/, '');
  for (let index = 0; index < input.length; index++) {
    const character = input[index];
    if (quoted) {
      if (character === '"') {
        if (input[index + 1] === '"') { field += '"'; index++; } else quoted = false;
      } else field += character;
    } else if (character === '"') quoted = true;
    else if (character === ',') { row.push(field); field = ''; }
    else if (character === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
    else if (character !== '\r') field += character;
  }
  if (field || row.length) { row.push(field); rows.push(row); }
  return { headers: rows[0], rows: rows.slice(1) };
}

const sampleCache = new Map();
function sample(file) {
  if (!sampleCache.has(file)) sampleCache.set(file, parseCsv(readFileSync(`${SAMPLE_DIR}${file}`, 'utf8')));
  return sampleCache.get(file);
}

const cellHtml = (value, numeric) => value === '' ? '<td class="blank">(blank)</td>' : `<td${numeric ? ' class="num"' : ''}>${esc(value)}</td>`;
function table(headers, rows, { caption = '', numeric = [] } = {}) {
  return `<div class="guide-table"><table>${caption ? `<caption>${caption}</caption>` : ''}<thead><tr>${headers.map((header) => `<th scope="col">${esc(header)}</th>`).join('')}</tr></thead><tbody>${rows.map((row) => `<tr>${row.map((value, index) => cellHtml(value, numeric.includes(headers[index]))).join('')}</tr>`).join('')}</tbody></table></div>`;
}

function rowsFrom(file, keys, columns, { key, ...options } = {}) {
  const { headers, rows } = sample(file);
  const keyIndex = headers.indexOf(key ?? headers[0]);
  const indexes = columns.map((column) => {
    const index = headers.indexOf(column);
    if (index < 0) throw new Error(`${file} has no column ${column}`);
    return index;
  });
  const picked = keys.map((value) => {
    const row = rows.find((entry) => entry[keyIndex] === value);
    if (!row) throw new Error(`${file} has no row ${value}`);
    return indexes.map((index) => row[index]);
  });
  return table(columns, picked, options);
}

function sampleBlock(file, label, { preview = 5, full = true, note = '' } = {}) {
  const { headers, rows } = sample(file);
  const shown = Math.min(preview, rows.length);
  return `<div class="tfg-sample"><p><strong>${label}</strong>: <a href="${ASSET}samples/${file}" download>${file}</a> · ${rows.length} rows, ${headers.length} columns, fictional data.${note ? ` ${note}` : ''}</p>${table(headers, rows.slice(0, shown), { caption: shown === rows.length ? 'All rows' : `First ${shown} rows` })}${full && rows.length > shown ? `<details><summary>Show all ${rows.length} rows</summary>${table(headers, rows)}</details>` : ''}</div>`;
}

const settings = (pairs) => `<p class="tfg-note">Macro settings, shortened to the start of each label. One value per line where shown on separate lines.</p><dl class="tfg-settings">${pairs.map(([name, value]) => `<dt>${name}</dt><dd>${value}</dd>`).join('')}</dl>`;
const files = (items) => `<ul class="tfg-files">${items.map(([path, name, description]) => `<li><a href="${ASSET}${path}" download>${name}</a><span>${description}</span></li>`).join('')}</ul>`;
const code = (text) => `<pre class="tfg-code"><code>${esc(text)}</code></pre>`;
const guide = (id, text) => `<a href="${ROOT}guides/${R[id].slug}/">${text ?? R[id].h1}</a>`;

const todayNote = '<p class="notice">The worked examples use <strong>Monday 9 November 2026</strong> as today. Relative date presets follow each reader’s device calendar, so on another day the same rule matches different rows. Where it matters, a fixed date range that reproduces the published result is included.</p>';
const setupSample = (file) => `<ol><li>Edit a Confluence page and insert the <strong>Flint Table Filter</strong> macro.</li><li>Inside the macro, add a native Confluence table whose first row is a header row with the column names from <a href="${ASSET}samples/${file}" download>${file}</a>, then enter or paste the data rows. If you paste from a spreadsheet, check that the result is an editable Confluence table rather than an image or an embedded file.</li><li>Publish the page. Search, <strong>Filters</strong>, <strong>Sort</strong>, <strong>Columns</strong>, <strong>Summary</strong>, <strong>Export</strong>, <strong>Expand table</strong> and <strong>Reset view</strong> appear above the published table.</li></ol>`;

function related(ids, extra = []) {
  return `<section class="tfg-related" aria-labelledby="related-help"><h2 id="related-help">Related help</h2><ul>${ids.map((id) => `<li>${guide(id)}</li>`).join('')}${extra.map((item) => `<li>${item}</li>`).join('')}<li>The <a href="${ROOT}table-filter/">Flint Table Filter product guide</a> lists every setting and limit.</li><li><a href="${ROOT}guides/table-filter/">All Flint Table Filter guides</a></li></ul></section>`;
}

function render(id, { description, lede, result, body }) {
  const route = R[id];
  return {
    title: route.title,
    description,
    ogImage: OG_IMAGE,
    body: `<link rel="stylesheet" href="${ASSET}guides.css"><article class="tfg-article"><p class="tfg-crumbs"><a href="${ROOT}guides/">Guides</a> / <a href="${ROOT}guides/table-filter/">Flint Table Filter</a></p><p class="eyebrow">FLINT TABLE FILTER · ${route.kind.toUpperCase()}</p><h1>${route.h1}</h1><p class="lede">${lede}</p><div class="tfg-result">${result}</div>${body}</article>`,
  };
}

